using UnityEngine;
using System.Collections.Generic;

public class GamePlane : MonoBehaviour
{
    public GameObject[] gems; // Array de gemas
    public int rows; // Número de filas en el tablero
    public int columns; // Número de columnas en el tablero
    public int gaps; // Espacio entre las gemas

    private List<Gem> gemList; // Lista de gemas

    void Start()
    {
        // Inicializa el tablero con gemas aleatorias
        gemList = new List<Gem>();
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < columns; j++)
            {
                int gemType = (int)System.Random.Range(0, System.Enum.GetValues(typeof(GemType)).Length);
                Gem gem = Instantiate(gems[gemType]) as Gem;
                gem.transform.position = new Vector3(j * gaps, i * gaps, 0);
                gem.SetType((GemType)gemType);
                gemList.Add(gem);
            }
        }
    }
}
```
