    // Si no se incluyó al menos una letra minúscula, agrega una al azar
    if (!hasLower) password += this.characters.charAt(Math.floor(Math.random() * this.characters.length));

    // Si no se incluyó al menos un número, agrega uno al azar
    if (!hasNumber) password += this.characters.charAt(Math.floor(Math.random() * this.characters.length));

