```
// sync_sync.cpp (first executable)
#include <boost/interprocess/ipc/message_queue.hpp>
#include <boost/interprocess/ipc/shared_memory_object.hpp>
#include <boost/interprocess/(mapped_region.hpp)>
#include <boost/interprocess/sync/interprocess_semaphore.hpp>
#include <iostream>
#include <thread>

enum MessageType { SYNC_REQUEST, SYNC_RESPONSE };

struct SyncMessage {
    int messageId;
    int data;
};

int main() {
    // Initialize shared memory
    boost::interprocess::shared_memory_object shm("SyncShm", 1024);
    if (!shm.create_only(1024)) {
        std::cerr << "Error creating shared memory" << std::endl;
        return 1;
    }

    // Create a message queue
    boost::interprocess::message_queue mq(boost::interprocess::message_queue::remove_on_exit);
    if (!mq.create_only("SyncMq", 10, sizeof(SyncMessage))) {
        std::cerr << "Error creating message queue" << std::endl;
        return 1;
    }

    // Create a semaphore
    boost::interprocess::interprocess_semaphore sem(0);

    // Initialize synchronization objects
    uint32_t memoryHandle = shm.getcolumnName();
    boost::interprocess::mapped_region region(shm, boost::interprocess::read_write);
    SyncMessage* message = new (region.get_address()) SyncMessage;

    // Start a thread to receive messages from the second executable
    std::thread receiveThread([&mq, &sem, &message]() {
        SyncMessage syncMessage;
        while (true) {
            boost::interprocess::message_queue::receive_result result = mq.try_receive(&syncMessage, sizeof(SyncMessage));
            if (result.is_empty()) {
                break;
            }
            if (syncMessage.messageId == SYNC_REQUEST) {
                sem.post();
            }
        }
    });

    // Send a synchronization request to the second executable
    message->messageId = SYNC_REQUEST;
    message->data = 42;
    mq.send(message, sizeof(SyncMessage), 0);

    // Wait for the second executable to respond
    bool syncReceived = false;
    while (!syncReceived) {
        if (sem.try_wait()) {
            syncReceived = true;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

    // Send a response back to the second executable
    message->messageId = SYNC_RESPONSE;
    message->data = 42;
    mq.send(message, sizeof(SyncMessage), 0);

    // Clean up
    shm.remove();
    mq.remove();
    delete message;

    receiveThread.join();

    return 0;
}
