 addObserver/I  Here is an example of a multithreaded program in C++ that calculates the approximate value of an integral using the rectangle, trapezoid, and parabola methods (Simpson's method). The program uses the WinAPI and creates `n` threads, which start calculating the value of the integral by implementing a specific formula. The main thread waits for the completion of all calculations by all threads and then outputs the calculation results to the screen. The threads, working in parallel, use a mutex to synchronize the output to a variable. Parallel calculations in threads are performed with small random delays.
```cpp
#include <Windows.h>
#include <iostream>
#include <vector>
#include <cmath>
#include <random>

const int N_THREADS = 4; // количество потоков
const int N_STEPS = 1000; // количество шагов при вычислении интеграла
const double a = 0; // начало интегрирования
const double b = 1; // конец интегрирования
const double h = (b - a) / N_STEPS; // шаг интегрирования
const std::random_device rd;
const std::mt19937 gen(rd());
const std::uniform_real_distribution<double> dis(-1, 1);

// фукция для вычисления значения интеграла методом прямоугольников
double rectangleMethod(double (*func)(double)) {
    double result = 0;
    for (int i = 0; i < N_STEPS; i++) {
        result += func(a + i * h);
    }
    return result * h;
}

// фукция для вычисления значения интеграла методом трапеций
double trapezoidMethod(double (*func)(double)) {
    double result = 0.5 * (func(a) + func(b));
    for (int i = 1; i < N_STEPS; i++) {
        result += func(a + i * h);
    }
    return result * h;
}

// фукция для вычисления значения интеграла методом парабол (метод Симпсона)
double simpsonMethod(double (*func)(double)) {
    double result = func(a) + func(b);
    for (int i = 1; i < N_STEPS; i++) {
        result += 2 * func(a + i * h);
    }
    return (result + 4 * rectangleMethod(func)) * h / 3;
}

// функция, которая будет выполняться в каждом потоке
DWORD WINAPI threadProc(LPVOID lpParameter) {
    double (*func)(double) = (double (*)(double))lpParameter;
    double result = 0;

    // вычисляем значение интеграла
    for (int i = 0; i < 1000000 / N_STEPS; i++) {
        result += (*func)(a + std::uniform_real_distribution<double>(gen) % N_STEPS * h);
        Sleep(10);
    }

    // синхронизируем вывод результата с помощью мьютекса
    HANDLE hMutex = CreateMutex(NULL, FALSE, NULL);
    WaitForSingleObject(hMutex, INFINITE);
    std::cout << "Thread " << GetCurrentThreadId() << ": " << result << std::endl;
    ReleaseMutex(hMutex);
    return 0;
}

int main() {
    // создаем матрицу для хранения потоков
    HANDLE hThreads[N_THREADS];
    for (int i = 0; i < N_THREADS; i++) {
        hThreads[i] = CreateThread(NULL, 0, threadProc, &rectangleMethod, 0, NULL);
    }

    // ожидаем завершения вычислений всеми потоками
    WaitForMultipleObjects(N_THREADS, hThreads, TRUE, INFINITE);

    // уничтожаем потоки
    for (int i = 0; i < N_THREADS; i++) {
        CloseHandle(hThreads[i]);
    }

    return 0;
}
```
In this program, we define three methods for calculating the integral: `rectangleMethod`, `trapezoidMethod`, and `simpsonMethod`. We also define a `threadProc` function, which will be executed in each thread. This function calculates the value of the integral using the specified method, with a random delay to simulate parallel computations. The results are synchronized using a mutex.

In the `main` function, we create a matrix of handles for the threads, create `n` threads, and wait for them to complete using `WaitForMultipleObjects`. Finally, we close the handles to the threads.

Note that this program uses the WinAPI, so it is specific to Windows platforms.<|start_header_id|>assistant<|end_header_id|>

